	private boolean isSelected(String playerName)
	{
		return selectedPlayerName != null
			&& TrackedMember.normalizeKey(selectedPlayerName).equals(TrackedMember.normalizeKey(playerName));
	}

	private void toggleSelectedPlayer(String playerName)
	{
		if (isSelected(playerName))
		{
			selectedPlayerName = null;
		}
		else
		{
			selectedPlayerName = playerName;
			ensureGrindingSummaryLoaded(playerName);
		}
		rebuild();
	}

	private void ensureGrindingSummaryLoaded(String playerName)
	{
		String cacheKey = grindingCacheKey(playerName);
		if (!config.enableWiseOldManLookups() && config.gainDataSource() == GainDataSource.TRACKER_APIS)
		{
			grindingSummaryCache.put(cacheKey, "Player gains are disabled.<br>Enable lookups in settings.");
			return;
		}
		if (grindingSummaryCache.containsKey(cacheKey))
		{
			return;
		}
		grindingSummaryCache.put(cacheKey, "Loading gains<br>for " + config.gainsPeriod().label() + "...");
		long generation = beginLookup(cacheKey);
		new SwingWorker<String, Void>()
		{
			@Override
			protected String doInBackground() throws Exception
			{
				return fetchConfiguredSummary(playerName);
			}

			@Override
			protected void done()
			{
				try
				{
					if (!applyLookupResult(cacheKey, generation, get()))
					{
						return;
					}
				}
				catch (Exception ex)
				{
					// done() runs on Swing's EDT; never perform fallback network/disk I/O here.
					if (!applyLookupResult(cacheKey, generation, "Tracker lookup failed.<br>Refresh to try again."))
					{
						return;
					}
				}
				rebuild();
			}
		}.execute();
	}

	long beginLookup(String cacheKey)
	{
		return lookupGenerations.begin(cacheKey);
	}

	boolean applyLookupResult(String cacheKey, long generation, String summary)
	{
		if (!lookupGenerations.isCurrent(cacheKey, generation))
		{
			return false;
		}
		grindingSummaryCache.put(cacheKey, summary);
		return true;
	}

	String cachedSummary(String cacheKey)
	{
		return grindingSummaryCache.get(cacheKey);
	}

	private void invalidateLookups()
	{
		lookupGenerations.invalidateAll();
		grindingSummaryCache.clear();
	}

	private String fetchConfiguredSummary(String playerName)
	{
		if (config.gainDataSource() == GainDataSource.OFFICIAL_HISCORES)
		{
			return fetchOfficialSummary(playerName);
		}
		return fetchWomSummary(playerName);
	}

	String testFetchConfiguredSummary(String playerName)
	{
		return fetchConfiguredSummary(playerName);
	}

	private String fetchWomSummary(String playerName)
	{
		try
		{
			GrindingSummaryOutcome womResult = gainedClient.fetchOutcome(playerName, config.gainsPeriod());
			if (womResult.hasPositiveGains())
			{
				// Explicit player scans also build fallback history without polling the social list.
				captureOfficialSnapshotAsync(playerName);
				return womResult.summary();
			}
			return fetchOfficialSummary(playerName);
		}
		catch (Exception ex)
		{
			// WOM failed - fall back to official hiscores
			return fetchOfficialSummary(playerName);
		}
	}

	private void captureOfficialSnapshotAsync(String playerName)
	{
		snapshotExecutor.execute(() -> {
			try
			{
				hiscoresClient.fetchGrindingSummary(playerName, config.gainsPeriod());
			}
			catch (Exception ignored)
			{
				// Optional history capture must not replace valid WOM data.
			}
		});
	}

	private String fetchOfficialSummary(String playerName)
	{
		try
		{
			return hiscoresClient.fetchGrindingSummary(playerName, config.gainsPeriod());
		}
		catch (Exception ignored)
		{
			return "Gains unavailable.<br>Refresh to try again.";
		}
	}

	private String grindingSummaryFor(String playerName)
	{
		return grindingSummaryCache.getOrDefault(grindingCacheKey(playerName), "Loading gains<br>for " + config.gainsPeriod().label() + "...");
	}

	private String grindingCacheKey(String playerName)
	{
		return LookupGenerationGuard.key(playerName, config.gainsPeriod().wiseOldManPeriod(), config.gainDataSource().name());
	}

	private JLabel cardLine(String html, float fontSize)
	{
		JLabel label = new JLabel("<html><body style='width:" + PANEL_TEXT_WIDTH + "px; margin:0; padding:0'>"
			+ html + "</body></html>");
		label.setForeground(Color.LIGHT_GRAY);
		label.setFont(label.getFont().deriveFont(Font.PLAIN, fontSize));
		label.setBorder(BorderFactory.createEmptyBorder(0, 0, 0, 0));
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		label.setMaximumSize(new Dimension(PANEL_TEXT_WIDTH, label.getPreferredSize().height));
		return label;
	}

	private String activityIcon(TrackedMember member)
	{
		if (member.status() == TrackedMemberStatus.ONLINE)
		{
			return "●";
		}
		if (member.hasSource(TrackedMemberSource.FRIENDS_CHAT))
		{
			return "◇";
		}
		return "○";
	}

	private String escapeHtml(String text)
	{
		return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}
}

package com.itmeansbigmountain.whosgrindingclanpanel;

