import java.util.concurrent.atomic.AtomicInteger;
import org.junit.Test;

public class OfficialHiscoresGainedClientTest
{
	@Test
	public void eachScanReplacesThePreviousSnapshotAndUsesOnlyTheImmediatePriorScan() throws IOException
	{
		Path cache = Files.createTempDirectory("hiscores-cache");
		Instant first = Instant.parse("2026-09-01T00:00:00Z");
		List<String> currentRows = new ArrayList<>(baselineRows());
		OfficialHiscoresGainedClient firstClient = new OfficialHiscoresGainedClient(
			cache,
			Clock.fixed(first, ZoneOffset.UTC),
			ignored -> OfficialHiscoresGainedClient.parseLiteCsv(baselineRows())
		);

		String baselineMessage = firstClient.fetchGrindingSummary("  Test Player!?  ", GainsPeriod.DAY);

		assertTrue(baselineMessage.contains("Scan saved"));
		assertFalse(baselineMessage.toLowerCase().contains("official"));
		Path snapshot = firstClient.snapshotFileFor("Test Player!?");
		assertTrue(snapshot.getFileName().toString().matches("[0-9a-f]{64}\\.csv"));
		assertFalse(snapshot.getFileName().toString().contains("test"));
		assertTrue(Files.isRegularFile(snapshot));

		currentRows.set(1, "1,2,250");
		currentRows.set(25 + 10, "1,9");
		currentRows.set(25 + 16 + 69, "1,4");
		OfficialHiscoresGainedClient secondClient = new OfficialHiscoresGainedClient(
			cache,
			Clock.fixed(first.plusSeconds(60), ZoneOffset.UTC),
			ignored -> OfficialHiscoresGainedClient.parseLiteCsv(currentRows)
		);

		String delta = secondClient.fetchGrindingSummary("test_player!?", GainsPeriod.DAY);

		assertTrue(delta.contains("Attack: <b>+250 xp</b>"));
		assertTrue(delta.contains("LMS: <b>+9 score</b>"));
		assertTrue(delta.contains("Zulrah: <b>+4 kc</b>"));
		assertEquals(1, OfficialHiscoresGainedClient.testReadSnapshots(snapshot).size());

		currentRows.set(1, "1,2,300");
		OfficialHiscoresGainedClient thirdClient = new OfficialHiscoresGainedClient(
			cache,
			Clock.fixed(first.plusSeconds(120), ZoneOffset.UTC),
			ignored -> OfficialHiscoresGainedClient.parseLiteCsv(currentRows)
		);

		String thirdDelta = thirdClient.fetchGrindingSummary("test_player!?", GainsPeriod.YEAR);

		assertTrue(thirdDelta.contains("Attack: <b>+50 xp</b>"));
		assertTrue(thirdDelta.contains("since<br>previous plugin scan"));
		assertTrue(thirdDelta.contains("Previous snapshot:<br>2026-09-01 00:01 UTC"));
		assertFalse(thirdDelta.contains("365"));
		List<OfficialHiscoresGainedClient.HiscoreSnapshot> retained = OfficialHiscoresGainedClient.testReadSnapshots(snapshot);
		assertEquals(1, retained.size());
		assertEquals(first.plusSeconds(120).getEpochSecond(), retained.get(0).testTimestamp());
	}

	@Test
	public void collisionProneNamesUseDistinctSnapshotFiles() throws IOException
	{
		Path cache = Files.createTempDirectory("hiscores-identity");
		OfficialHiscoresGainedClient client = new OfficialHiscoresGainedClient(
			cache, Clock.systemUTC(), ignored -> OfficialHiscoresGainedClient.parseLiteCsv(baselineRows()));

		Path punctuationA = client.snapshotFileFor("A!B");
		Path punctuationB = client.snapshotFileFor("A?B");

		assertFalse(punctuationA.equals(punctuationB));
		assertTrue(punctuationA.getFileName().toString().matches("[0-9a-f]{64}\\.csv"));
		assertTrue(punctuationB.getFileName().toString().matches("[0-9a-f]{64}\\.csv"));
	}

	@Test
	public void migratesLegacyUnhashedSnapshotBeforeComparing() throws IOException
	{
		Path cache = Files.createTempDirectory("hiscores-legacy-name");
		Instant now = Instant.parse("2026-09-08T00:00:00Z");
		Path legacy = cache.resolve("legacy_player.csv");
		Files.write(legacy, List.of((now.minusSeconds(60).getEpochSecond()) + ",V2|S{Attack=10}|A{}|B{}"));
		List<String> rows = new ArrayList<>(baselineRows());
		rows.set(1, "1,2,25");
		OfficialHiscoresGainedClient client = new OfficialHiscoresGainedClient(
			cache, Clock.fixed(now, ZoneOffset.UTC), ignored -> OfficialHiscoresGainedClient.parseLiteCsv(rows));

		String result = client.fetchGrindingSummary("Legacy_Player", GainsPeriod.DAY);

		assertTrue(result.contains("+15 xp"));
		assertFalse(Files.exists(legacy));
		assertTrue(Files.exists(client.snapshotFileFor("Legacy Player")));
	}

	@Test
	public void explicitScanRemovesOrphanTemporarySiblingBeforeReplacingSnapshot() throws IOException
	{
		Path cache = Files.createTempDirectory("hiscores-orphan-temp");
		OfficialHiscoresGainedClient client = new OfficialHiscoresGainedClient(
			cache, Clock.systemUTC(), ignored -> OfficialHiscoresGainedClient.parseLiteCsv(baselineRows()));
		Path target = client.snapshotFileFor("Test Player");
