		Path target = Files.write(directory.resolve("snapshot.csv"), List.of("old"));
		AtomicInteger attempts = new AtomicInteger();

		OfficialHiscoresGainedClient.replaceAtomically(temporary, target, (source, destination, options) -> {
			if (attempts.getAndIncrement() == 0)
			{
